def nbr(b,i,j):
    n=0
    for di in(-1,0,1):
        for dj in(-1,0,1):
            if di==0 and dj==0: continue
            y,x=i+di,j+dj
            if 0<=y<b.shape[0] and 0<=x<b.shape[1] and b[y,x]: n+=1
    return n

def feats2(sub):
    b=sub>0; h,w=b.shape
    degs={}
    ends=junc=straight=0
    for i in range(h):
        for j in range(w):
            if b[i,j]:
                d=nbr(b,i,j)
                if d==1: ends+=1
                if d>=3: junc+=1
                if d==2 and ((b[i-1,j] and b[i+1,j]) if 0<i<h-1 else False) or (d==2 and 0<j<w-1 and b[i,j-1] and b[i,j+1]): straight+=1
    # loops: cells - per/2 + ... use cyclomatic: E - V + 1 (for connected, 8-conn approx edges as adjacent pairs)
    E=0
    for i in range(h):
        for j in range(w):
            if b[i,j]:
                for di,dj in [(0,1),(1,0),(1,1),(1,-1)]:
                    y,x=i+di,j+dj
                    if 0<=y<h and 0<=x<w and b[y,x]: E+=1
    V=int(b.sum())
    return dict(ends=ends,junc=junc,cyc=E-V+1)

for name,gg in [('demo1',d1),('demo2',d2_),('test',ts)]:
    print('===',name)
    for i,c in enumerate(comps_of(gg)):
        print(i,feats(c),feats2(c))

